import {
  CatalogCourse,
  Department,
  PrereqAdjList,
  PrerequisiteJSON,
} from "@/typings";

import axios from "axios";
import createPersistedState from "vuex-persistedstate";

import Vue from "vue";
import VueAxios from "vue-axios";
import Vuex, { Store } from "vuex";

// eslint-disable-next-line
const SCHOOLS_JSON = require(`./data/semester_data/${process.env.VUE_APP_CURR_SEM}/schools.json`);
// eslint-disable-next-line
const REGISTRATION_DATES_JSON = require(`./data/semester_data/${process.env.VUE_APP_CURR_SEM}/registration_dates.json`);

import DATA_STATS_JSON from "./data/meta.json";
import PREREQ_GRAPH_JSON from "./data/prereq_graph.json";

import settings from "./modules/settings";
import prerequisites from "./modules/prerequisites";
import schedule from "./modules/schedule";

Vue.use(Vuex);

const SEMESTER_STORAGE_KEY =
  process.env.VUE_APP_CURR_SEM === "202101"
    ? "vuex"
    : (process.env.VUE_APP_CURR_SEM as string);
const INTER_SEMESTER_STORAGE_KEY = "inter-semester-storage";

// Each tab only reads localStorage on load, so without this a second tab
// overwrites whatever the first tab saved. The storage event fires in every
// other tab when one tab writes, so pull the new value into this tab's state.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function syncAcrossTabs(store: Store<any>): void {
  window.addEventListener("storage", (event) => {
    if (
      event.newValue === null ||
      (event.key !== SEMESTER_STORAGE_KEY &&
        event.key !== INTER_SEMESTER_STORAGE_KEY)
    ) {
      return;
    }
    const saved = JSON.parse(event.newValue);
    const schedule = store.state.schedule;
    const previous = {
      ...schedule.courseSets[schedule.currentTerm]?.[schedule.currentCourseSet],
    };

    const next = { ...store.state };
    for (const module in saved) {
      next[module] = { ...store.state[module], ...saved[module] };
    }
    store.replaceState(next);

    if (event.key === SEMESTER_STORAGE_KEY) {
      store.dispatch("schedule/resyncSelectedSections", previous);
    }
  });
}
Vue.use(VueAxios, axios);

export default new Vuex.Store({
  state: {
    schools: SCHOOLS_JSON as {
      name: string;
      depts: { code: string; name: string }[];
    }[],
    registrationDates: REGISTRATION_DATES_JSON as {
      registration_opens: string;
      registration_closes: string;
    },
    dataStats: DATA_STATS_JSON as { last_updated: string },
    departments: [] as Department[], // asynchronously loaded
    catalog: {} as { [id: string]: CatalogCourse }, // asynchronously loaded
    prerequisitesData: {} as { [id: string]: PrerequisiteJSON }, // asynchronously loaded
    prereqGraph: PREREQ_GRAPH_JSON as PrereqAdjList,
    lastNewSchedule: 0,
    warningMessage: "",
    updateAvailable: false,
  },
  getters: {
    shouldShowAlert: (state) => {
      return state.warningMessage !== "";
    },

    warningMessage: (state) => {
      return state.warningMessage;
    },

    departmentsInitialized: (state) => {
      return state.departments.length > 0;
    },

    catalogInitialized: (state) => {
      return Object.keys(state.catalog).length !== 0;
    },

    prerequisitesDataInitialized: (state) => {
      return state.prerequisitesData !== {};
    },
  },
  mutations: {
    SET_DEPARTMENTS(state, departments): void {
      state.departments = departments;
    },

    SET_CATALOG(state, catalog): void {
      state.catalog = catalog;
    },

    SET_PREREQUISITES_DATA(state, data): void {
      state.prerequisitesData = data;
    },

    setWarningMessage(state, message): void {
      state.warningMessage = message;
    },

    toggleUpdateNotice(state, newValue: boolean): void {
      state.updateAvailable = newValue;
    },
  },
  actions: {
    init({ commit }): void {
      import(
        `./data/semester_data/${process.env.VUE_APP_CURR_SEM}/catalog.json`
      ).then((catalog) => commit("SET_CATALOG", catalog));

      import(
        `./data/semester_data/${process.env.VUE_APP_CURR_SEM}/courses.json`
      ).then((departments) => commit("SET_DEPARTMENTS", departments.default));

      import(
        `./data/semester_data/${process.env.VUE_APP_CURR_SEM}/prerequisites.json`
      ).then((prereqs) => commit("SET_PREREQUISITES_DATA", prereqs));
    },
  },
  modules: {
    settings,
    prerequisites,
    schedule,
  },
  plugins: [
    createPersistedState({
      key: SEMESTER_STORAGE_KEY,
      paths: [
        "schedule.storedVersion",
        "schedule.currentTerm",
        "schedule.currentCourseSet",
        "schedule.courseSets",
      ],
      rehydrated: (store) => {
        store
          .dispatch("schedule/init", false)
          .then(() => store.dispatch("schedule/initSelectedSetions"));
      },
    }),
    (store) => store.commit("schedule/ensureDefaultCourseSet"),
    createPersistedState({
      key: INTER_SEMESTER_STORAGE_KEY,
      paths: [
        "settings.timePreference",
        "settings.colorTheme",
        "settings.hidePrerequisites",
        "settings.hideAgentButton",
        "settings.enableTracking",
        "prerequisites.priorCourses",
        "prerequisites.enableChecking",
      ],
    }),
    syncAcrossTabs,
  ],
});
